/* No.011 */
(() => {
const TEX = {"front": "front.jpg", "back": "back.jpg"};
const MED_OUT = [[0.0781, 1.0], [0.3672, 0.877], [0.5059, 0.793], [0.6484, 0.6602], [0.7754, 0.4922], [0.8262, 0.3984], [0.8848, 0.2266], [0.9043, 0.0645], [0.9043, -0.1348], [0.8887, -0.2441], [0.8301, -0.4414], [0.7031, -0.6387], [0.5996, -0.752], [0.4766, -0.8496], [0.2461, -0.998], [-0.2461, -0.998], [-0.4805, -0.877], [-0.6191, -0.7852], [-0.7441, -0.668], [-0.8496, -0.5273], [-1.0, -0.2402], [-1.0, 0.2402], [-0.8145, 0.5801], [-0.7168, 0.6973], [-0.5801, 0.8145], [-0.2402, 1.0]];
const MED_H = {"b16": 1, "n": 220, "x0": -1, "x1": 1, "y0": 1, "y1": -1, "h": ""};
/* No.011 clear acrylic button with a gold Tudor-rose medallion sealed inside.
   The body uses transmission, so the medallion is seen through the clear acrylic from every side. */
function buildK() {
  const grp = new THREE.Group();
  const clear = new THREE.MeshPhysicalMaterial({
    color: 0xfffdf6, metalness: 0, roughness: .03, transmission: 1, thickness: .5, ior: 1.49,
    attenuationColor: new THREE.Color(0xfff2c8), attenuationDistance: 2.2,
    clearcoat: 1, clearcoatRoughness: .02, specularIntensity: 1, envMapIntensity: 1.2, side: THREE.DoubleSide
  });
  // body profile: flat face with a rounded rim, domed back
  const prof = [];
  prof.push([0, .17]);
  for (let i = 1; i <= 10; i++) prof.push([.86 * i / 10, .17 - .01 * i / 10]);
  for (let i = 1; i <= 12; i++) { const a = i / 12 * Math.PI / 2; prof.push([.86 + .14 * Math.sin(a), .16 - .18 * (1 - Math.cos(a))]); }
  for (let i = 1; i <= 16; i++) { const t = i / 16; prof.push([1 - .02 * t - .98 * Math.pow(t, 1.6) , -.02 - .26 * Math.sin(t * Math.PI / 2)]); }
  prof.push([0, -.28]);
  const lg = new THREE.LatheGeometry(prof.map(([r, z]) => new THREE.Vector2(r, z)).reverse(), 160);
  lg.rotateX(Math.PI / 2);
  // sealed medallion: gold relief facing up, its back facing down; both scaled into the middle of the body
  const gTex = tex(TEX.front);
  const gold = new THREE.MeshStandardMaterial({ map: gTex, emissiveMap: gTex, color: 0xffffff, emissive: 0xffffff, emissiveIntensity: .35, metalness: .7, roughness: .25, envMapIntensity: 1.1, side: THREE.DoubleSide });
  const goldBack = new THREE.MeshStandardMaterial({ map: tex(TEX.back), color: 0xffeec0, metalness: .85, roughness: .3, envMapIntensity: 1.1, side: THREE.DoubleSide });
  const med = new THREE.Group();
  med.add(new THREE.Mesh(cloverRelief(MED_H, .0, .035), gold));
  med.add(new THREE.Mesh(cloverRelief(MED_H, -.02, -.03), goldBack));
  const pos = [], idx = [], n = MED_OUT.length;
  MED_OUT.forEach(([x, y]) => pos.push(x, y, .02, x, y, -.025));
  for (let i = 0; i < n; i++) { const j = (i + 1) % n; idx.push(2 * i, 2 * j, 2 * i + 1, 2 * j, 2 * j + 1, 2 * i + 1); }
  const wg = new THREE.BufferGeometry(); wg.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3)); wg.setIndex(idx); wg.computeVertexNormals();
  med.add(new THREE.Mesh(wg, new THREE.MeshStandardMaterial({ color: 0xd9b45a, metalness: 1, roughness: .25, envMapIntensity: 1.3, side: THREE.DoubleSide })));
  med.scale.set(.76, .76, .76); med.position.z = .03;
  grp.add(med);
  grp.add(new THREE.Mesh(lg, clear));
  // clear shank ridge on the back, split by the thread notch
  const ang = Math.atan2(-1.32, -.32);
  const backZ = (x, y) => { const r = Math.min(1, Math.hypot(x, y)); return -.02 - .26 * Math.cos(Math.min(1, r) * Math.PI / 2) + .02; };
  grp.add(new THREE.Mesh(stripRot(.0, -.02, ang, .14, .62, .2, backZ, .07, false), clear));
  grp.add(new THREE.Mesh(stripRot(.0, -.02, ang, -.62, -.14, .2, backZ, .07, false), clear));
  return grp;
}
buildK.env = 'jewel';
viewer(document.getElementById('cv'), buildK, 'v');
})();
